import os, glob, re

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows_content = t[m.end():].split('\n')[:h]
        actual_rows = [r.split() for r in rows_content if r.strip()]
        if k not in G:
            # Validate all rows have correct width and are numeric
            valid = True
            for i, row in enumerate(actual_rows):
                if len(row) != w:
                    valid = False
                    break
                for x in row:
                    if not x.isdigit():
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                G[k] = [[int(x) for x in r] for r in actual_rows]
    return G

G = load()
print("Grids loaded:", sorted(G.keys()))
for k in sorted(G.keys()):
    h, w = len(G[k]), len(G[k][0]) if G[k] else 0
    print(f"\n=== {k} ({h}x{w}) ===")
    print(G[k])

