    if msg.get('role') == 'assistant':  # User prompt contains grids
        content = ''
        for part in msg.get('message', {}).get('content', [])[:1]:
            if isinstance(part, dict) and part.get('type') == 'text':
                content += part.get('text', '')
            elif isinstance(part, str):
                content += part

        # Find test input
        import re
        test_match = re.search(r'Test input \((\d+)x(\d+)\):(.*?)Reply with exactly one action', content, re.DOTALL)
        if test_match:
            h, w = int(test_match.group(1)), int(test_match.group(2))
            grid_text = test_match.group(3).strip().replace('\n', '').replace('\\n', '\n')
            rows = []
            current_row = []
            for ch in grid_text:
                if ch == ' ':
                    if current_row:
                        rows.append([int(x) for x in current_row])
                        current_row = []
                elif ch.isdigit():
                    current_row.append(ch)
            if current_row:
                rows.append([int(x) for x in current_row])
            if len(rows) > 0 and len(rows[0]) == w:
                grids['Test input'] = rows

    # Check demo pairs
    elif msg.get('role') == 'user':
        content = ''
        for part in msg.get('content', [])[:1]:
            if isinstance(part, dict) and part.get('type') == 'text':
                content += part.get('text', '')

        demo_input = re.search(r'Demo pair (\d+) input \((\d+)x(\d+)\):(.*?)(?=Demo pair|\Z)', content, re.DOTALL)
        demo_output = re.search(r'Demo pair (\d+) output \((\d+)x(\d+)\):(.*?)(?=Same instance|\Z)', content, re.DOTALL)

        if demo_input and demo_output:
            d_num, h_in, w_in = int(demo_input.group(1)), int(demo_input.group(2)), int(demo_input.group(3))
            d_out_num, h_out, w_out = int(demo_output.group(1)), int(demo_output.group(2)), int(demo_output.group(3))

            def parse_grid(text):
                grid_rows = []
                for row_line in text.strip().split('\n'):
                    parts = [p for p in row_line.split() if p]
                    grid_rows.append([int(p) for p in parts])
                return grid_rows

            grids[f'Demo pair {d_num} input'] = parse_grid(demo_input.group(4).strip())
            grids[f'Demo pair {d_out_num} output'] = parse_grid(demo_output.group(4).strip())
            break  # Found what we need

print("Grids found:", list(grids.keys()))

